79: // emphasize wraps the text between the first pair of markers in the given
80: // tag. If the text contains fewer than two markers it is returned unchanged.
81: func emphasize(text, marker, tag string) string {
82: 	start := strings.Index(text, marker)
83: 	if start < 0 {
84: 		return text
85: 	}
86: 	rest := text[start+len(marker):]
87: 	end := strings.Index(rest, marker)
88: 	if end < 0 {
89: 		return text
90: 	}
91: 	return text[:start] + "<" + tag + ">" + rest[:end] + "</" + tag + ">" + rest[end+len(marker):]
92: }
